import {AnimationBlendSpace,animationAxisValue,snapAnimationSample,animationBlendModes,animationAxisSmoothing} from './animation-blend-space.js';
const modes={cartesian:'Cartesian · 삼각 혼합',directional:'Simple Directional · 방향 혼합',freeformDirectional:'Freeform Directional · 방향·속도 혼합'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderAnimationBlendSpace(editor,node,base){const p=node.properties;return editor.input('혼합 방식',base+'.mode',p.mode,'text',animationBlendModes.map(k=>[k,modes[k]]))+editor.parameter('X 파라미터',base+'.parameterX',p.parameterX,'float',false)+editor.parameter('Y 파라미터',base+'.parameterY',p.parameterY,'float',false)+'<svg class="anim-blend-space" viewBox="0 0 280 270" tabindex="0" role="group" aria-label="2차원 혼합 샘플"></svg><output data-blend-readout></output>'+['x','y'].map(k=>'<details data-sync-section="blend-axis-'+k+'"><summary>'+k.toUpperCase()+' 축 · '+esc(p.axes[k].name)+'</summary>'+editor.input('이름',base+'.axes.'+k+'.name',p.axes[k].name)+['min','max','divisions','smoothing'].map((field,i)=>editor.input(['최솟값','최댓값','격자 수','보정 시간'][i],base+'.axes.'+k+'.'+field,p.axes[k][field],'number')).join('')+editor.input('보정 방식',base+'.axes.'+k+'.smoothingType',p.axes[k].smoothingType,'text',animationAxisSmoothing.map(v=>[v,v==='linear'?'Linear':'Exponential']))+editor.input('격자에 맞추기',base+'.axes.'+k+'.snap',p.axes[k].snap,'checkbox')+editor.input('범위 순환',base+'.axes.'+k+'.wrap',p.axes[k].wrap,'checkbox')+'</details>').join('');}
export function addAnimationBlendSample(node,position){const p=node.properties,samples=p.samples;if(samples.length>=64)throw Error('혼합 샘플 한도64');let i=0;while(samples.some(s=>s.input==='pose'+i))i++;if(!position){outer:for(let y=0;y<=p.axes.y.divisions;y++)for(let x=0;x<=p.axes.x.divisions;x++){const xy=[p.axes.x.min+x*(p.axes.x.max-p.axes.x.min)/p.axes.x.divisions,p.axes.y.min+y*(p.axes.y.max-p.axes.y.min)/p.axes.y.divisions];if(!samples.some(s=>Math.hypot(s.x-xy[0],s.y-xy[1])<1e-8)){position=xy;break outer;}}}if(!position)throw Error('비어 있는 샘플 좌표를 지정하세요.');samples.push({input:'pose'+i,x:position[0],y:position[1]});return 'pose'+i;}
export function drawAnimationBlendSpace(editor,node,parameters,runtime){
  const chart=editor.element.querySelector('.anim-blend-space');if(!chart||node?.type!=='blend2d')return;const p=node.properties;if(editor.blendProperties!==p){editor.blendProperties=p;editor.blendProgram=new AnimationBlendSpace(p);editor.blendWeights=new Float64Array(p.samples.length);}const program=editor.blendProgram;
  const input=[p.parameterX,p.parameterY].map((name,i)=>animationAxisValue(parameters?.[name]??editor.previewValues[name]??editor.doc.data.parameters.find(p=>p.name===name)?.value??0,p.axes[i?'y':'x'])),value=runtime?.value||input,weights=runtime?Float64Array.from(p.samples.map(s=>runtime.samples[s.input]||0)):program.sample(...value,editor.blendWeights),sx=v=>30+(v-p.axes.x.min)*230/(p.axes.x.max-p.axes.x.min),sy=v=>235-(v-p.axes.y.min)*210/(p.axes.y.max-p.axes.y.min),selected=editor.blendSelection?.node===node.id?editor.blendSelection.input:'';
  const viewKey=JSON.stringify([input,value,[...weights],selected,editor.blendDrag?.value]);if(chart.dataset.blendViewKey===viewKey)return;chart.dataset.blendViewKey=viewKey;
  const geometry=program.triangles.map(ids=>'<path class="blend-triangle" d="M '+ids.map(i=>sx(p.samples[i].x)+' '+sy(p.samples[i].y)).join(' L ')+' Z"/>').join(''),grid=['x','y'].map(k=>Array.from({length:p.axes[k].divisions+1},(_,i)=>{const v=p.axes[k].min+i*(p.axes[k].max-p.axes[k].min)/p.axes[k].divisions;return k==='x'?'<path class="blend-grid" d="M '+sx(v)+' 25 V 235"/>':'<path class="blend-grid" d="M 30 '+sy(v)+' H 260"/>';}).join('')).join('');
  chart.innerHTML=grid+geometry+p.samples.map((s,i)=>{const xy=editor.blendDrag?.input===s.input?editor.blendDrag.value:[s.x,s.y];return '<g data-blend-sample="'+esc(s.input)+'" class="'+(s.input===selected?'selected':'')+'"><circle class="blend-weight" cx="'+sx(xy[0])+'" cy="'+sy(xy[1])+'" r="'+(6+weights[i]*17)+'"/><circle class="blend-point" cx="'+sx(xy[0])+'" cy="'+sy(xy[1])+'" r="5"/><text x="'+sx(xy[0])+'" y="'+(sy(xy[1])-10)+'" text-anchor="middle">'+(i+1)+'</text><title>'+esc(editor.doc.data.nodes.find(n=>n.id===node.inputs[s.input])?.name||'포즈 '+(i+1))+' · '+s.x+', '+s.y+' · '+(weights[i]*100).toFixed(1)+'%</title></g>';}).join('')+'<path class="blend-input" d="M '+(sx(input[0])-5)+' '+sy(input[1])+' h 10 M '+sx(input[0])+' '+(sy(input[1])-5)+' v 10"/><circle class="blend-value" cx="'+sx(value[0])+'" cy="'+sy(value[1])+'" r="3"/><text x="30" y="252">'+p.axes.x.min+'</text><text x="260" y="252" text-anchor="end">'+p.axes.x.max+'</text><text x="145" y="267" text-anchor="middle">'+esc(p.axes.x.name)+'</text><text x="3" y="22">'+p.axes.y.max+'</text><text x="3" y="235">'+p.axes.y.min+'</text><text x="30" y="14">'+esc(p.axes.y.name)+'</text>';
  editor.element.querySelector('[data-blend-readout]').textContent='X '+value[0].toFixed(2)+' · Y '+value[1].toFixed(2)+' · '+p.samples.map((s,i)=>i+1+': '+Math.round(weights[i]*100)+'%').join(' / ');
  const coords=event=>{const r=chart.getBoundingClientRect(),x=p.axes.x.min+((event.clientX-r.x)*280/r.width-30)*(p.axes.x.max-p.axes.x.min)/230,y=p.axes.y.min+(235-(event.clientY-r.y)*270/r.height)*(p.axes.y.max-p.axes.y.min)/210;return [snapAnimationSample(x,{...p.axes.x,snap:p.axes.x.snap||event.shiftKey}),snapAnimationSample(y,{...p.axes.y,snap:p.axes.y.snap||event.shiftKey})];},scrub=event=>{const xy=coords(event);for(let i=0;i<2;i++){const name=i?p.parameterY:p.parameterX;editor.previewValues[name]=xy[i];const field=editor.element.querySelector('[data-anim-preview-param="'+name+'"]');if(field)field.value=xy[i];}editor.drawBlendChart();};
  chart.onpointerdown=event=>{if(editor.hooks.running()||event.button!==0)return;event.preventDefault();chart.focus();chart.setPointerCapture(event.pointerId);const sample=event.target.closest('[data-blend-sample]');if(sample&&!event.ctrlKey){const s=p.samples.find(s=>s.input===sample.dataset.blendSample);editor.blendSelection={node:node.id,input:s.input};editor.blendDrag={input:s.input,value:[s.x,s.y],from:[s.x,s.y],moved:false};editor.drawBlendChart();}else{editor.blendScrub=true;scrub(event);}};
  chart.onpointermove=event=>{if(!chart.hasPointerCapture(event.pointerId))return;if(editor.blendDrag){editor.blendDrag.value=coords(event);editor.blendDrag.moved=true;editor.drawBlendChart();}else if(editor.blendScrub)scrub(event);};
  chart.onpointerup=event=>{const drag=editor.blendDrag;editor.blendDrag=null;editor.blendScrub=false;if(chart.hasPointerCapture(event.pointerId))chart.releasePointerCapture(event.pointerId);if(drag?.moved&&!editor.hooks.running())editor.change(d=>{const s=d.nodes.find(n=>n.id===node.id).properties.samples.find(s=>s.input===drag.input);[s.x,s.y]=drag.value;});else editor.drawBlendChart();};chart.onpointercancel=()=>{editor.blendDrag=null;editor.blendScrub=false;editor.drawBlendChart();};
  const remove=()=>editor.change(d=>{const n=d.nodes.find(n=>n.id===node.id),index=n.properties.samples.findIndex(s=>s.input===selected);if(index<0)return;n.properties.samples.splice(index,1);delete n.inputs[selected];editor.blendSelection=null;});
  chart.onkeydown=event=>{if(!['Delete','Enter','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();event.stopPropagation();if(editor.hooks.running())return;if(event.key==='Delete'){remove();return;}const i=p.samples.findIndex(s=>s.input===selected);if(i<0)return;if(event.key==='Enter'){const index=editor.doc.data.nodes.indexOf(node);editor.element.querySelector('[data-anim-field="nodes.'+index+'.properties.samples.'+i+'.x"]')?.focus();return;}editor.change(d=>{const s=d.nodes.find(n=>n.id===node.id).properties.samples[i],key=['ArrowLeft','ArrowRight'].includes(event.key)?'x':'y',axis=p.axes[key];s[key]=snapAnimationSample(s[key]+(axis.max-axis.min)/axis.divisions*(event.shiftKey?10:1)*(['ArrowLeft','ArrowDown'].includes(event.key)?-1:1),axis);});editor.element.querySelector('.anim-blend-space')?.focus();};
  chart.oncontextmenu=event=>{event.preventDefault();if(editor.hooks.running())return;const sample=event.target.closest('[data-blend-sample]');if(sample)editor.blendSelection={node:node.id,input:sample.dataset.blendSample};editor.element.querySelector('.anim-node-menu')?.remove();const xy=coords(event),menu=editor.element.ownerDocument.createElement('div'),r=editor.element.getBoundingClientRect();menu.className='anim-node-menu';menu.style.left=Math.max(0,Math.min(editor.element.clientWidth-275,event.clientX-r.x))+'px';menu.style.top=Math.max(0,Math.min(editor.element.clientHeight-100,event.clientY-r.y))+'px';menu.innerHTML='<button data-blend-add>포즈 추가 · '+xy.map(v=>v.toFixed(2)).join(', ')+'</button>'+(sample?'<button data-blend-delete>샘플 삭제</button>':'');menu.onclick=e=>{if(e.target.closest('[data-blend-add]'))editor.change(d=>{const input=addAnimationBlendSample(d.nodes.find(n=>n.id===node.id),xy);editor.blendSelection={node:node.id,input};});else if(e.target.closest('[data-blend-delete]')){const input=sample.dataset.blendSample;editor.change(d=>{const n=d.nodes.find(n=>n.id===node.id);n.properties.samples=n.properties.samples.filter(s=>s.input!==input);delete n.inputs[input];});}};editor.element.append(menu);};
}
